export type Lang = 'en' | 'pl' | 'ru';

let _lang: Lang = (localStorage.getItem('lang') as Lang) || 'en';

export function getLang(): Lang { return _lang; }

export function setLang(lang: Lang): void {
  _lang = lang;
  localStorage.setItem('lang', lang);
}

export function t(key: string): string {
  const entry = (TRANSLATIONS as Record<string, Record<string, string>>)[key];
  if (!entry) {
    if (import.meta.env.DEV) console.warn(`[i18n] Missing key: "${key}"`);
    return key;
  }
  const val = entry[_lang] || entry['en'];
  return val || key;
}

export function localName(nameObj: Record<string, string>): string {
  return nameObj[_lang] || nameObj['en'] || '';
}

export function syncLangFromUser(user: { language?: string } | null): void {
  if (localStorage.getItem('lang')) return;
  if (user?.language) {
    const lang = user.language.toLowerCase() as Lang;
    if (['ru', 'pl', 'en'].includes(lang)) setLang(lang);
  }
}

