    "guide.punk.res.desc":            { ru: "Ранг рассчитывается по процентному показателю средневзвешенной оценки. Чем выше процент — тем лучше объект.", pl: "Ranking obliczany jest na podstawie procentowego wskaźnika średniej ważonej. Im wyższy procent — tym lepszy obiekt.", en: "Rank is based on the weighted average percentage. Higher percentage means a better object." },
    "guide.punk.res.r1":              { ru: "Таблица оценок — полная матрица критериев × объекты с итоговыми строками.", pl: "Tabela ocen — pełna macierz kryteriów × obiekty z wierszami podsumowującymi.", en: "Scores table — full criteria × objects matrix with summary rows." },
    "guide.punk.res.r2":              { ru: "Диаграмма: нажмите на кружок в легенде, чтобы скрыть или показать линию объекта.", pl: "Wykres: kliknij kółko w legendzie, aby ukryć lub pokazać linię obiektu.", en: "Chart: click a circle in the legend to hide or show an object's line." },

    "guide.aud.step1.title":        { ru: "Audyt — параметры и критерии", pl: "Audyt — parametry i kryteria", en: "Audit — parameters & criteria" },
    "guide.aud.step1.desc":         { ru: "Настройте число аудиторов и пороговые значения, затем добавьте критерии оценки. Параметры сохраняются автоматически.", pl: "Skonfiguruj liczbę audytorów i progi, następnie dodaj kryteria oceny. Parametry zapisują się automatycznie.", en: "Configure number of auditors and thresholds, then add evaluation criteria. Parameters save automatically." },
    "guide.aud.step1.r1":           { ru: "Аудиторов: минимум 2. Критериев: минимум 2.", pl: "Audytorów: minimum 2. Kryteriów: minimum 2.", en: "Auditors: minimum 2. Criteria: minimum 2." },
    "guide.aud.step1.r2":           { ru: "Принятие критерия % — минимальный процент от максимально возможной суммы баллов по критерию, при котором критерий считается принятым.", pl: "Akceptacja kryterium % — minimalny procent od maksymalnej możliwej sumy punktów dla kryterium, przy którym kryterium jest uznane za przyjęte.", en: "Criterion acceptance % — minimum percentage of the maximum possible score per criterion for it to be accepted." },
    "guide.aud.step1.r3":           { ru: "Принятие системы % — минимальный процент принятых критериев, при котором вся система управления качеством считается принятой.", pl: "Akceptacja systemu % — minimalny procent przyjętych kryteriów, przy którym cały system zarządzania jakością jest uznany za przyjęty.", en: "System acceptance % — minimum percentage of accepted criteria for the entire quality management system to be accepted." },
    "guide.aud.step1.r4":           { ru: "Количество аудиторов и оба процентных параметра — только целые числа. Процентные значения допустимы в диапазоне 1–100.", pl: "Liczba audytorów i oba parametry procentowe — tylko liczby całkowite. Wartości procentowe mieszczą się w zakresie 1–100.", en: "Auditor count and both percentage parameters are integers only. Percentage values must be between 1 and 100." },
    "guide.aud.step2.title":        { ru: "Audyt — оценки аудиторов", pl: "Audyt — oceny audytorów", en: "Audit — auditor scores" },
    "guide.aud.step2.desc":         { ru: "Сначала задайте шкалу оценок, затем каждый аудитор выставляет баллы по каждому критерию. Ячейки вне диапазона подсвечиваются красным.", pl: "Najpierw ustaw skalę, następnie każdy audytor wystawia oceny dla każdego kryterium. Komórki poza zakresem zaznaczono czerwonym.", en: "Set the score scale first, then each auditor rates every criterion. Out-of-range cells are highlighted red." },
    "guide.aud.step2.r1":           { ru: "Шкала сохраняется при потере фокуса. При изменении шкалы ячейки вне нового диапазона нужно скорректировать до расчёта.", pl: "Skala zapisuje się po utracie fokusu. Po zmianie skali należy poprawić komórki poza nowym zakresem przed obliczeniem.", en: "Scale saves on blur. After changing the scale, fix any out-of-range cells before calculating." },
    "guide.aud.step2.r2":           { ru: "Ячейки вне диапазона шкалы подсвечиваются красным.", pl: "Komórki poza zakresem skali zaznaczane są na czerwono.", en: "Cells outside the scale range are highlighted red." },
    "guide.aud.step2.r3":           { ru: "Оценка сохраняется при переходе к следующей ячейке (потере фокуса).", pl: "Ocena zapisuje się przy przejściu do następnej komórki.", en: "A score saves when you move to the next cell (on blur)." },
    "guide.aud.step2.r4":           { ru: "Границы шкалы — только целые числа. Оценки принимаются до двух знаков после запятой.", pl: "Granice skali muszą być liczbami całkowitymi. Oceny przyjmowane są do dwóch miejsc po przecinku.", en: "Scale boundaries must be integers. Scores are accepted up to two decimal places." },
    "guide.aud.step3.title":        { ru: "Audyt — результаты", pl: "Audyt — wyniki", en: "Audit — results" },
    "guide.aud.step3.desc":         { ru: "Все значения пересчитываются на лету — только по аудиторам 1..N, указанным в параметрах.", pl: "Wszystkie wartości przeliczane są na bieżąco — tylko dla audytorów 1..N z parametrów.", en: "All values are computed live — only for auditors 1..N set in parameters." },
    "guide.aud.step3.r1":           { ru: "Критерий принят, если Шкала % ≥ Принятие критерия %.", pl: "Kryterium przyjęte, gdy Skala % ≥ Akceptacja kryterium %.", en: "Criterion accepted if Scale % ≥ Criterion acceptance %." },
    "guide.aud.step3.r2":           { ru: "Система принята, если % принятых критериев ≥ Принятие системы %.", pl: "System przyjęty, gdy % przyjętych kryteriów ≥ Akceptacja systemu %.", en: "System accepted if % of accepted criteria ≥ System acceptance %." },

